#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import argparse,json,queue,threading,time
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
import serial

L=threading.Lock();dist=[-1]*181;ts=0.0
CL=threading.Lock();C=[]
D=json.dumps

def b(o):
  m=D(o,separators=(",",":"))
  with CL:
    dead=[]
    for q in C:
      try:q.put_nowait(m)
      except queue.Full:dead.append(q)
    for q in dead:
      try:C.remove(q)
      except ValueError:pass

def p(s):
  s=s.strip()
  if ":" not in s:return
  a,d=s.split(":",1)
  try:a=int(a);d=int(d)
  except:return
  if 0<=a<=180:return a,d

def sl(port,baud):
  global ts
  ser=None
  while 1:
    try:
      if ser is None:
        ser=serial.Serial(port,baudrate=baud,timeout=1);time.sleep(.2)
        try:ser.reset_input_buffer()
        except:pass
      r=ser.readline()
      if not r:continue
      x=p(r.decode("utf-8","ignore"))
      if not x:continue
      a,d=x;t=time.time()
      with L:dist[a]=d;ts=t
      b({"a":a,"d":d,"t":t})
    except serial.SerialException:
      try:ser.close()
      except:pass
      ser=None;time.sleep(.5)
    except:time.sleep(.01)

HTML=r'''<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Sonar180 Aframe example</title>
<script src="https://aframe.io/releases/1.5.0/aframe.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/aframe-orbit-controls-component@0.2.0/dist/aframe-orbit-controls-component.min.js"></script>
<style>html,body{height:100%;margin:0;background:#070a0f}a-scene{position:fixed;inset:0}</style>
<a-scene vr-mode-ui="enabled:false" embedded background="color:#070a0f" renderer="antialias:true;colorManagement:true;physicallyCorrectLights:true">
<a-assets><img id=tex src="data:image/jpeg;base64,"></a-assets>
<a-entity light="type:ambient;intensity:.6"></a-entity><a-entity light="type:point;intensity:5" position="0.04 0.5 0.3"></a-entity>
<a-plane scale="0.297 0.297 0.297" rotation="-90 0 0" width="50" height="50" material="src:#tex;metalness:.8;opacity:.2;roughness:0"></a-plane>
<a-entity id=camRig position="0 .5 3.2" rotation="-45 0 0" orbit-controls="target:0 .8 0;enableDamping:true;dampingFactor:.12;rotateSpeed:.25;zoomSpeed:.9;minDistance:.6;maxDistance:25"><a-camera fov=60 position="0 3 1"></a-camera></a-entity>
<a-entity id=pts></a-entity></a-scene>
<script>
(()=>{const P=document.getElementById("pts"),mc=300,r0=.25,r1=7,cl=(v,a,b)=>v<a?a:v>b?b:v,rad=a=>(a-90)*Math.PI/180,R=d=>r0+(r1-r0)*cl(d/mc,0,1),
pal=t=>(t=cl(t,0,1))<.2?"#ff2020":t<.4?"#ffd000":t<.6?"#30ff30":t<.8?"#2f7bff":"#2a0a4a";
function box(a){let e=document.getElementById("p"+a);if(e)return e;e=document.createElement("a-box");e.id="p"+a;
e.setAttribute("width",".07");e.setAttribute("depth",".07");e.setAttribute("height",".60");e.setAttribute("material","metalness:0;roughness:.9");
e.setAttribute("visible","false");P.appendChild(e);return e}
function upd(a,d){let e=box(a);if(!(d>=0&&isFinite(d))){e.setAttribute("visible","false");return}
let r=rad(a),rr=R(d),x=Math.sin(r)*rr,z=-Math.cos(r)*rr,t=cl(d/mc,0,1);
e.setAttribute("position",`${x.toFixed(3)} .30 ${z.toFixed(3)}`);
e.setAttribute("rotation",`0 ${(a-90).toFixed(1)} 0`);
e.setAttribute("material",`color:${pal(t)};metalness:0;roughness:.1`);
e.setAttribute("visible","true")}
new EventSource("/events").onmessage=e=>{try{let m=JSON.parse(e.data);upd(m.a|0,m.d|0)}catch{}};
})();
</script>'''

class H(BaseHTTPRequestHandler):
  def log_message(self,*a): pass
  def do_GET(self):
    p=self.path
    if p=="/" or p[:6]=="/index":
      b=HTML.encode();self.send_response(200)
      self.send_header("Content-Type","text/html; charset=utf-8")
      self.send_header("Content-Length",str(len(b)))
      self.end_headers();self.wfile.write(b);return
    if p.startswith("/events"):
      self.send_response(200)
      self.send_header("Content-Type","text/event-stream")
      self.send_header("Cache-Control","no-cache")
      self.send_header("Connection","keep-alive")
      self.end_headers()
      q=queue.Queue(maxsize=600)
      with CL: C.append(q)
      with L: s={"dist":dist,"t":ts}
      try:
        self.wfile.write((f"data:{D(s,separators=(',',':'))}\n\n").encode()); self.wfile.flush()
      except:
        with CL:
          if q in C: C.remove(q)
        return
      try:
        while 1:
          try:
            m=q.get(timeout=15)
            self.wfile.write((f"data:{m}\n\n").encode()); self.wfile.flush()
          except queue.Empty:
            self.wfile.write(b":\n\n"); self.wfile.flush()
      except: pass
      finally:
        with CL:
          if q in C: C.remove(q)
      return
    self.send_response(404); self.end_headers(); self.wfile.write(b"404")

def main():
  a=argparse.ArgumentParser()
  a.add_argument("--port",required=True)
  a.add_argument("--baud",type=int,default=115200)
  a.add_argument("--http",type=int,default=8000)
  a=a.parse_args()
  threading.Thread(target=sl,args=(a.port,a.baud),daemon=True).start()
  ThreadingHTTPServer(("0.0.0.0",a.http),H).serve_forever()

if __name__=="__main__": main()
